from typing import Optional
import math
import os.path

import matplotlib.pyplot as plt
import numpy as np
def draw_graph(tar_dir,data_pair:(list,list),name,dir_name):

    O_python = np.array(data_pair[0])
    O_scade = np.array(data_pair[1])
    print(O_python)
    print(O_scade)
    print(name)
    # 创建阶梯图
    # plt.step(T,O, where='mid', label='VehicleSpeed * 10', color='black', linewidth=2)
    # plt.step(T, I1, where='mid', label='CruiseSpeed', color='red', linewidth=1, linestyle='--')
    plt.step(np.array(range(1, len(O_python.data) + 1)), O_python, where='mid', label='python', color='green', linewidth=1, linestyle='--')
    plt.step(np.array(range(1, len(O_scade.data) + 1)), O_scade, where='mid', label='scade', color='red', linewidth=1, linestyle='--')
    # 添加标题和标签
    plt.title(name, fontsize=14)

    # 添加图例
    plt.legend(fontsize=10)

    # # 显示网格
    # plt.grid(True, linestyle='--', alpha=0.7)
    # plt.xticks(np.arange(0, len(O_python.data) + 1, 1))
    # plt.yticks(np.arange(0,4,1))
    # 显示图表
    if not os.path.exists(tar_dir):
        os.makedirs(tar_dir)
    plt.savefig(f"{tar_dir}/{name}.png")
    plt.clf()

